<?php
$pageTitle='Ticket manager'; require_once 'includes/auth.php'; require_auth(); $u=current_user(); $pid=(int)($_GET['project']??$_POST['project_id']??0);$s=$pdo->prepare('SELECT * FROM projects WHERE id=? AND company_id=?');$s->execute([$pid,$u['company_id']]);$project=$s->fetch();if(!$project){http_response_code(404);exit('Project not found.');}
$members=[];if(is_manager()){$s=$pdo->prepare('SELECT id,full_name FROM users WHERE company_id=? AND role<>"manager" ORDER BY full_name');$s->execute([$u['company_id']]);$members=$s->fetchAll();}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';if($a==='ticket'){$assigned=is_manager()&&$_POST['assigned_to']!==''?(int)$_POST['assigned_to']:null;$priority=is_manager()&&in_array($_POST['priority'],['urgent','important','normal'],true)?$_POST['priority']:'normal';$s=$pdo->prepare('INSERT INTO tickets(project_id,title,description,expected_outcome,expected_submit_date,priority,assigned_to,created_by) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$pid,trim($_POST['title']),trim($_POST['description']),trim($_POST['expected_outcome']),$_POST['expected_submit_date']?:null,$priority,$assigned,$u['id']]);flash('success','Ticket created and assigned.');}elseif($a==='subtask'){$s=$pdo->prepare('INSERT INTO subtasks(ticket_id,title) VALUES(?,?)');$s->execute([(int)$_POST['ticket_id'],trim($_POST['subtask_title'])]);}elseif($a==='close_subtask'){$s=$pdo->prepare('UPDATE subtasks SET is_closed=1,closed_at=NOW() WHERE id=?');$s->execute([(int)$_POST['subtask_id']]);}elseif($a==='close_ticket'){$s=$pdo->prepare('UPDATE tickets SET status="Closed",closed_at=NOW() WHERE id=? AND project_id=?');$s->execute([(int)$_POST['ticket_id'],$pid]);flash('success','Ticket closed.');}header('Location: tickets.php?project='.$pid);exit;}
$s=$pdo->prepare('SELECT t.*,u.full_name assignee FROM tickets t LEFT JOIN users u ON u.id=t.assigned_to WHERE t.project_id=? ORDER BY FIELD(t.priority,"urgent","important","normal"),t.created_at DESC');$s->execute([$pid]);$tickets=$s->fetchAll();foreach($tickets as &$t){$q=$pdo->prepare('SELECT * FROM subtasks WHERE ticket_id=?');$q->execute([$t['id']]);$t['subtasks']=$q->fetchAll();}unset($t);require 'includes/header.php';
?><style>.ticket-priority{border-left:4px solid #22c55e}.ticket-priority.urgent{border-left-color:#dc2626}.ticket-priority.important{border-left-color:#eab308}.priority{display:inline-block;padding:4px 8px;border-radius:4px;font-size:10px;font-weight:800;text-transform:uppercase}.priority.urgent{background:#fee2e2;color:#b91c1c}.priority.important{background:#fef3c7;color:#92400e}.priority.normal{background:#dcfce7;color:#166534}</style><div class="section-head"><div><p class="eyebrow">Project</p><h2><?=e($project['name'])?></h2></div><a class="button button-light" href="projects.php">← Back</a></div><div class="grid grid-2"><div><?php foreach($tickets as $t): ?><article class="ticket ticket-priority <?=e($t['priority'])?>"><div class="ticket-head"><div><h3><?=e($t['title'])?></h3><span class="priority <?=e($t['priority'])?>"><?=ucfirst(e($t['priority']))?></span> <span class="badge badge-<?=strtolower($t['status'])==='closed'?'closed':'open'?>"><?=e($t['status'])?></span><p class="muted">Responsible: <?=e($t['assignee']?:'Unassigned')?></p></div><?php if($t['status']!=='Closed'): ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="close_ticket"><input type="hidden" name="ticket_id" value="<?=$t['id']?>"><button class="button button-light">Close</button></form><?php endif; ?></div><p><?=e($t['description'])?></p><p><strong>Outcome:</strong> <?=e($t['expected_outcome']?:'—')?> · <strong>Due:</strong> <?=e($t['expected_submit_date']?:'—')?></p><div class="subtasks"><strong style="font-size:11px">Subtasks</strong><?php foreach($t['subtasks'] as $st): ?><div class="subtask <?=$st['is_closed']?'done':''?>"><span><?=e($st['title'])?></span><?php if(!$st['is_closed']): ?><form method="post" style="margin-left:auto"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="close_subtask"><input type="hidden" name="subtask_id" value="<?=$st['id']?>"><button class="button button-light">Done</button></form><?php endif; ?></div><?php endforeach; ?><form method="post" style="display:flex;gap:7px;margin-top:12px"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="subtask"><input type="hidden" name="ticket_id" value="<?=$t['id']?>"><input name="subtask_title" placeholder="Add a subtask" required style="flex:1;padding:8px;border:1px solid var(--line);border-radius:5px;font-size:12px"><button class="button button-light">Add</button></form></div></article><?php endforeach; ?><?php if(!$tickets): ?><div class="card empty">No tickets yet.</div><?php endif; ?></div><div class="card"><h2 style="font-size:16px;margin:0 0 18px"><?=is_manager()?'Issue and assign ticket':'New ticket'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="ticket"><input type="hidden" name="project_id" value="<?=$pid?>"><div class="field"><label>Title</label><input name="title" required></div><?php if(is_manager()): ?><div class="form-grid" style="margin-top:13px"><div class="field"><label>Priority</label><select name="priority"><option value="urgent">Red · Urgent</option><option value="important">Yellow · Important</option><option value="normal" selected>Green · Normal</option></select></div><div class="field"><label>Responsible employee</label><select name="assigned_to"><option value="">Unassigned</option><?php foreach($members as $member): ?><option value="<?=$member['id']?>"><?=e($member['full_name'])?></option><?php endforeach; ?></select></div></div><?php endif; ?><div class="field" style="margin-top:13px"><label>Description</label><textarea name="description"></textarea></div><div class="field" style="margin-top:13px"><label>Expected outcome</label><textarea name="expected_outcome"></textarea></div><div class="field" style="margin-top:13px"><label>Expected submission date</label><input type="date" name="expected_submit_date"></div><div class="form-actions"><button class="button button-red"><?=is_manager()?'Issue ticket':'Create ticket'?></button></div></form></div></div><?php require 'includes/footer.php';
